.voice-pill {
  --vp-accent: #f5f5f5;
  --vp-icon: #a1a1aa;
  --vp-bg: #27272a;
  --vp-size: 28px;
  --vp-radius: 14px;
  --vp-reach: 8px;
  --vp-extra: 0px;
  --vp-clock-w: 0px;
  --vp-wave-w: 0px;
  --vp-slide: 0px;
  --vp-cancel: 0;
  --vp-stop: 9px;
  --vp-icon-size: 15px;
  --vp-time-size: 10px;
  --vp-open: 200ms;
  --vp-press: 0.95;
  --vp-hit: 8px;
  --vp-ease-out: cubic-bezier(0.23, 1, 0.32, 1);

  position: relative;
  display: inline-grid;
  place-items: center;
  isolation: isolate;
  width: var(--vp-size);
  height: var(--vp-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--vp-radius);
  background: transparent;
  color: var(--vp-icon);
  font-family: inherit;
  cursor: pointer;
  outline: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
  transition:
    transform 160ms var(--vp-ease-out),
    color 150ms ease;
}

.voice-pill::before {
  content: '';
  position: absolute;
  inset: calc(-1 * var(--vp-hit));
}

.voice-pill[data-state='listening'] {
  z-index: 1;
  color: var(--vp-accent);
}

.voice-pill[data-pressed] {
  transform: scale(var(--vp-press));
}

.voice-pill:disabled {
  opacity: 0.55;
  cursor: default;
  pointer-events: none;
}

.voice-pill__capsule {
  position: absolute;
  inset: 0 0 0 calc(-1 * (var(--vp-reach) + var(--vp-extra)));
  border-radius: var(--vp-radius);
  background: var(--vp-bg);
  clip-path: inset(0 0 0 calc(var(--vp-reach) + var(--vp-extra)) round var(--vp-radius));
  pointer-events: none;
  transition:
    clip-path var(--vp-open) var(--vp-ease-out),
    background-color 150ms ease;
}

@media (hover: hover) and (pointer: fine) {
  .voice-pill[data-state='idle']:not(:disabled):hover .voice-pill__capsule {
    background: color-mix(in srgb, var(--vp-icon) 10%, var(--vp-bg));
  }
}

.voice-pill[data-state='listening'] .voice-pill__capsule {
  clip-path: inset(0 0 round var(--vp-radius));
}

.voice-pill__time {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 100%;
  display: grid;
  place-items: center;
  width: var(--vp-clock-w);
  box-sizing: border-box;
  color: var(--vp-accent);
  font-size: var(--vp-time-size);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  opacity: 0;
  filter: blur(2px);
  transform: translateX(var(--vp-slide));
  pointer-events: none;
  transition:
    opacity 200ms ease,
    filter 200ms ease,
    transform 240ms var(--vp-ease-out);
}

.voice-pill[data-state='listening'] .voice-pill__time {
  opacity: calc(1 - var(--vp-cancel));
  filter: blur(0);
}

.voice-pill__wave {
  position: absolute;
  top: 18%;
  right: calc(100% + var(--vp-clock-w));
  width: var(--vp-wave-w);
  height: 64%;
  opacity: 0;
  filter: blur(2px);
  transform: translateX(var(--vp-slide));
  pointer-events: none;
  transition:
    opacity 200ms ease,
    filter 200ms ease,
    transform 240ms var(--vp-ease-out);
}

.voice-pill[data-state='listening'] .voice-pill__wave {
  opacity: calc(1 - var(--vp-cancel));
  filter: blur(0);
}

.voice-pill__cancel {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  width: var(--vp-extra);
  color: var(--vp-accent);
  font-size: var(--vp-time-size);
  font-weight: 500;
  line-height: 1;
  opacity: var(--vp-cancel);
  pointer-events: none;
}

.voice-pill[data-sliding] .voice-pill__time,
.voice-pill[data-sliding] .voice-pill__wave,
.voice-pill[data-sliding] .voice-pill__glyph {
  transition-property: opacity, filter;
}

.voice-pill__glyph {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--vp-size);
  height: var(--vp-size);
  transform: translateX(var(--vp-slide));
  transition: transform 240ms var(--vp-ease-out);
}

.voice-pill__glyph > * {
  grid-area: 1 / 1;
  transition:
    opacity 200ms ease,
    filter 200ms ease,
    transform 200ms var(--vp-ease-out);
}

.voice-pill__mic {
  display: inline-flex;
}

.voice-pill__stop {
  width: var(--vp-stop);
  height: var(--vp-stop);
  border-radius: 22%;
  background: currentColor;
  opacity: 0;
  filter: blur(2px);
  transform: scale(0.6);
}

.voice-pill[data-state='listening'] .voice-pill__mic {
  opacity: 0;
  filter: blur(2px);
  transform: scale(0.7);
}

.voice-pill[data-state='listening'] .voice-pill__stop {
  opacity: 1;
  filter: blur(0);
  transform: scale(1);
}

.voice-pill[data-input='key'] .voice-pill__capsule,
.voice-pill[data-input='key'] .voice-pill__time,
.voice-pill[data-input='key'] .voice-pill__glyph > * {
  transition-duration: 0ms;
}

@media (prefers-reduced-motion: reduce) {
  .voice-pill {
    transform: none !important;
    transition: color 150ms ease;
  }

  .voice-pill__capsule {
    transition: background-color 150ms ease;
  }

  .voice-pill__glyph > * {
    filter: none !important;
    transform: none !important;
    transition: opacity 200ms ease;
  }

  .voice-pill__time,
  .voice-pill__wave,
  .voice-pill__glyph {
    filter: none !important;
    transition-property: opacity;
  }
}

import { createEffect, createMemo, createSignal, onSettled, Show, untrack } from 'solid-js';
import type { JSX } from '@solidjs/web';
import { ArrowLeft01Icon, Mic01Icon } from '@hugeicons/core-free-icons';
import './VoicePill.css';

export type VoicePillShape = 'pill' | 'rounded';
export type VoicePillMode = 'auto' | 'hold' | 'toggle';
export type VoicePillSource = 'simulated' | 'mic';
export type VoicePillStopReason =
  'release' | 'tap' | 'key' | 'escape' | 'blur' | 'disabled' | 'mic-denied' | 'cancel' | 'unmount';

export interface VoicePillProps {
  accentColor?: string;
  iconColor?: string;
  background?: string;
  size?: number;
  shape?: VoicePillShape;
  reach?: number;
  showTime?: boolean;
  waveform?: boolean;
  slideToCancel?: boolean;
  cancelDistance?: number;
  attack?: number;
  release?: number;
  sensitivity?: number;
  floor?: number;
  openDuration?: number;
  pressScale?: number;
  mode?: VoicePillMode;
  holdAfter?: number;
  reactive?: VoicePillSource;
  disabled?: boolean;
  ariaLabel?: string;
  onStart?: (info: { source: VoicePillSource }) => void;
  onStop?: (info: { reason: VoicePillStopReason; duration: number }) => void;
  className?: string;
}

interface AudioBits {
  ctx: AudioContext;
  stream?: MediaStream | null;
  src?: MediaStreamAudioSourceNode | null;
  analyser?: AnalyserNode | null;
  buf?: Uint8Array<ArrayBuffer> | null;
}

interface State {
  listening: boolean;
  pointerId: number | null;
  ownPress: boolean;
  downX: number;
  sliding: boolean;
  hist: number[];
  tick: number;
  acc: number;
  downAt: number;
  startedAt: number;
  raf: number;
  last: number;
  env: number;
  t0: number;
  audio: AudioBits | null;
}

interface Cfg {
  attack: number;
  release: number;
  sensitivity: number;
  floor: number;
  mode: VoicePillMode;
  holdAfter: number;
  reactive: VoicePillSource;
  showTime: boolean;
  waveform: boolean;
  slideToCancel: boolean;
  cancelDistance: number;
  accentColor: string;
  disabled: boolean;
  onStart?: VoicePillProps['onStart'];
  onStop?: VoicePillProps['onStop'];
}

type IconNode = readonly (readonly [string, { readonly [key: string]: string | number }])[];

declare global {
  interface Window {
    webkitAudioContext?: typeof AudioContext;
  }
}

const LOOP = 4.8;
const SYLLABLES = [
  [0.1, 0.16, 0.9],
  [0.3, 0.12, 0.7],
  [0.5, 0.2, 1],
  [0.95, 0.14, 0.8],
  [1.15, 0.1, 0.6],
  [1.3, 0.22, 0.95],
  [1.9, 0.16, 0.85],
  [2.12, 0.12, 0.7],
  [2.3, 0.18, 0.9],
  [2.55, 0.1, 0.5],
  [3.05, 0.24, 1],
  [3.4, 0.12, 0.75],
  [3.6, 0.16, 0.9]
];
const MIC_BINS = [
  [1, 4],
  [4, 11],
  [11, 33]
];
const MIC_GAIN = 2.2;
const DT_MAX = 0.05;
const SLIDE_MIN = 4;
const WAVE_EVERY = 4;
const WAVE_MAX = 80;

const escapeAttr = (value: string | number) => String(value).replace(/&/g, '&amp;').replace(/"/g, '&quot;');

const iconMarkup = (icon: IconNode, strokeWidth: number) =>
  icon
    .map(([tag, attrs]) => {
      const parts = Object.entries({ ...attrs, strokeWidth, stroke: 'currentColor' })
        .filter(([key]) => key !== 'key')
        .map(([key, value]) => `${key.replace(/[A-Z]/g, char => `-${char.toLowerCase()}`)}="${escapeAttr(value)}"`);
      return `<${tag} ${parts.join(' ')}></${tag}>`;
    })
    .join('');

function Icon(props: { icon: IconNode; size: number; strokeWidth: number }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={props.size}
      height={props.size}
      viewBox="0 0 24 24"
      fill="none"
      color="currentColor"
      stroke="currentColor"
      stroke-width={props.strokeWidth}
      innerHTML={iconMarkup(props.icon, props.strokeWidth)}
    />
  );
}

const simulatedLevel = (t: number) => {
  const u = t % LOOP;
  let a = 0.06;
  for (const [s, d, p] of SYLLABLES) {
    const x = (u - s) / d;
    if (x >= 0 && x <= 1) a = Math.max(a, p * 0.5 * (1 - Math.cos(2 * Math.PI * x)));
  }
  return a * (0.7 + 0.3 * Math.abs(Math.sin(2 * Math.PI * 7.1 * u)));
};
const micLevel = (analyser: AnalyserNode, buf: Uint8Array<ArrayBuffer>) => {
  analyser.getByteFrequencyData(buf);
  let total = 0;
  for (const [lo, hi] of MIC_BINS) {
    let s = 0;
    for (let i = lo; i < hi; i += 1) s += buf[i];
    total += s / ((hi - lo) * 255);
  }
  return (total / MIC_BINS.length) * MIC_GAIN;
};
const drawWave = (s: State, canvas: HTMLCanvasElement, level: number, color: string, floor: number) => {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const rect = canvas.getBoundingClientRect();
  const W = Math.max(1, Math.round(rect.width * dpr));
  const H = Math.max(1, Math.round(rect.height * dpr));
  if (canvas.width !== W || canvas.height !== H) {
    canvas.width = W;
    canvas.height = H;
  }
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  s.acc = Math.max(s.acc, level);
  s.tick = (s.tick + 1) % WAVE_EVERY;
  if (s.tick === 0) {
    s.hist.push(s.acc);
    s.acc = 0;
    if (s.hist.length > WAVE_MAX) s.hist.shift();
  }
  const bw = 2 * dpr;
  const step = 3 * dpr;
  const shift = (s.tick / WAVE_EVERY) * step;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = color;
  for (let i = 0; i < s.hist.length; i += 1) {
    const v = s.hist[s.hist.length - 1 - i];
    const x = W - (i + 1) * step - shift;
    if (x + bw < 0) break;
    const h = Math.max(bw, (floor + (1 - floor) * v) * H);
    const t = Math.min(1, Math.max(0, (x + bw / 2) / (W * 0.55)));
    const fade = t * t * (3 - 2 * t);
    ctx.globalAlpha = (0.35 + 0.65 * v) * fade;
    ctx.beginPath();
    ctx.roundRect(x, (H - h) / 2, bw, h, bw / 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
};
const clock = (ms: number) => {
  const s = Math.floor(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
};

const openMic = async (s: State) => {
  const Ctx = window.AudioContext || window.webkitAudioContext;
  if (!Ctx || !navigator.mediaDevices?.getUserMedia) throw new Error('unsupported');
  s.audio ??= { ctx: new Ctx() };
  const a = s.audio;
  if (a.ctx.state === 'suspended') a.ctx.resume();
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  if (!s.listening) {
    stream.getTracks().forEach(t => t.stop());
    return;
  }
  a.stream = stream;
  a.src = a.ctx.createMediaStreamSource(stream);
  a.analyser = a.ctx.createAnalyser();
  a.analyser.fftSize = 256;
  a.analyser.smoothingTimeConstant = 0;
  a.src.connect(a.analyser);
  a.buf = new Uint8Array(a.analyser.frequencyBinCount);
};
const closeMic = (s: State) => {
  const a = s.audio;
  if (!a?.stream) return;
  a.stream.getTracks().forEach(t => t.stop());
  a.src?.disconnect();
  a.stream = null;
  a.src = null;
  a.analyser = null;
  a.buf = null;
};

export default function VoicePill(props: VoicePillProps) {
  const [listening, setListening] = createSignal(false);
  const [pressed, setPressed] = createSignal(false);
  const [input, setInput] = createSignal('pointer');
  let timeEl: HTMLSpanElement | undefined;
  let rootEl: HTMLButtonElement | undefined;
  let waveEl: HTMLCanvasElement | undefined;
  let disposed = false;
  const st: State = {
    listening: false,
    pointerId: null,
    ownPress: false,
    downX: 0,
    sliding: false,
    hist: [],
    tick: 0,
    acc: 0,
    downAt: 0,
    startedAt: 0,
    raf: 0,
    last: 0,
    env: 0,
    t0: 0,
    audio: null
  };

  const settings = createMemo<Cfg>(() => ({
    attack: props.attack ?? 40,
    release: props.release ?? 240,
    sensitivity: props.sensitivity ?? 1,
    floor: props.floor ?? 0.1,
    mode: props.mode ?? 'auto',
    holdAfter: props.holdAfter ?? 300,
    reactive: props.reactive ?? 'simulated',
    showTime: props.showTime ?? true,
    waveform: props.waveform ?? true,
    slideToCancel: props.slideToCancel ?? true,
    cancelDistance: props.cancelDistance ?? 64,
    accentColor: props.accentColor ?? '#f5f5f5',
    disabled: props.disabled ?? false,
    onStart: props.onStart,
    onStop: props.onStop
  }));
  let cfg: Cfg = untrack(settings);
  createEffect(settings, value => {
    cfg = value;
  });

  const size = () => props.size ?? 28;
  const showTime = () => props.showTime ?? true;
  const waveform = () => props.waveform ?? true;
  const disabled = () => props.disabled ?? false;
  const radius = () => ((props.shape ?? 'pill') === 'rounded' ? Math.round(size() * 0.29) : size() / 2);
  const hit = () => Math.max(0, Math.min(10, (44 - size()) / 2));
  const timeSize = () => Math.max(10, Math.round(size() * 0.36));
  const clockW = () => (showTime() ? Math.round(timeSize() * 2.5) + 4 : 0);
  const waveW = () => (waveform() ? Math.round(size() * 1.9) : 0);
  const extra = () => clockW() + waveW();

  const frame = (now: number) => {
    const s = st;
    const c = cfg;
    const dt = Math.min((now - s.last) / 1000, DT_MAX);
    s.last = now;
    let target = 0;
    if (s.listening) {
      if (s.audio?.analyser) target = micLevel(s.audio.analyser, s.audio.buf as Uint8Array<ArrayBuffer>);
      else if (c.reactive !== 'mic') target = simulatedLevel((now - s.t0) / 1000);
    }
    target = Math.min(1, target * c.sensitivity);
    const tau = Math.max(1, target > s.env ? c.attack : c.release) / 1000;
    s.env += (target - s.env) * (1 - Math.exp(-dt / tau));
    if (s.listening && c.showTime && timeEl) {
      const text = clock(now - s.startedAt);
      if (timeEl.textContent !== text) timeEl.textContent = text;
    }
    if (s.listening && c.waveform && waveEl) drawWave(s, waveEl, s.env, c.accentColor, c.floor);
    s.raf = s.listening ? requestAnimationFrame(frame) : 0;
  };

  const begin = (kind: 'pointer' | 'key') => {
    const s = st;
    const c = cfg;
    if (s.listening || c.disabled || disposed) return;
    s.listening = true;
    s.hist = [];
    s.tick = 0;
    s.acc = 0;
    s.env = 0;
    s.startedAt = performance.now();
    s.t0 = s.startedAt;
    s.last = s.startedAt;
    if (timeEl) timeEl.textContent = '0:00';
    setListening(true);
    setInput(kind);
    if (!s.raf) s.raf = requestAnimationFrame(frame);
    c.onStart?.({ source: c.reactive });
    if (c.reactive === 'mic') openMic(s).catch(() => end('mic-denied'));
  };
  const end = (reason: VoicePillStopReason) => {
    const s = st;
    const c = cfg;
    if (!s.listening) return;
    s.listening = false;
    closeMic(s);
    if (!disposed) {
      setListening(false);
      setInput(reason === 'key' || reason === 'escape' ? 'key' : 'pointer');
    }
    c.onStop?.({ reason, duration: Math.round(performance.now() - s.startedAt) });
  };

  const settleSlide = () => {
    const s = st;
    const root = rootEl;
    s.sliding = false;
    if (!root) return;
    delete root.dataset.sliding;
    root.style.setProperty('--vp-slide', '0px');
    root.style.setProperty('--vp-cancel', '0');
  };
  const onPointerMove = (e: PointerEvent) => {
    const s = st;
    const c = cfg;
    const root = rootEl;
    if (!root || s.pointerId !== e.pointerId || !c.slideToCancel || !s.listening || !s.ownPress) return;
    const dx = e.clientX - s.downX;
    if (!s.sliding && dx > -SLIDE_MIN) return;
    s.sliding = true;
    root.dataset.sliding = '';
    const pull = Math.min(c.cancelDistance + 24, Math.max(0, -dx));
    root.style.setProperty('--vp-slide', `${-pull}px`);
    const progress = Math.min(1, pull / c.cancelDistance);
    root.style.setProperty('--vp-cancel', progress.toFixed(3));
    if (progress >= 1) {
      settleSlide();
      end('cancel');
    }
  };
  const onPointerDown = (e: PointerEvent & { currentTarget: HTMLButtonElement }) => {
    const s = st;
    if (cfg.disabled || e.button !== 0 || !e.isPrimary || s.pointerId !== null) return;
    s.pointerId = e.pointerId;
    s.downX = e.clientX;
    s.downAt = performance.now();
    try {
      e.currentTarget.setPointerCapture(e.pointerId);
    } catch {}
    setPressed(true);
    s.ownPress = !s.listening;
    if (!s.listening) begin('pointer');
  };
  const onPointerUp = (e: PointerEvent & { currentTarget: HTMLButtonElement }) => {
    const s = st;
    const c = cfg;
    if (e.pointerId !== s.pointerId) return;
    s.pointerId = null;
    setPressed(false);
    if (s.sliding) settleSlide();
    try {
      if (e.currentTarget.hasPointerCapture(e.pointerId)) e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {}
    if (!s.listening) return;
    const held = performance.now() - s.downAt;
    const isHold = c.mode === 'hold' || (c.mode === 'auto' && held >= c.holdAfter);
    if (s.ownPress) {
      if (isHold) end('release');
    } else {
      end(held < c.holdAfter ? 'tap' : 'release');
    }
  };
  const onKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      end('escape');
      return;
    }
    if ((e.key === ' ' || e.key === 'Enter') && !e.repeat) {
      e.preventDefault();
      if (st.listening) end('key');
      else begin('key');
    }
  };
  const onClick = (e: MouseEvent) => {
    if (e.detail === 0 && st.pointerId === null && !(e as PointerEvent).pointerType) {
      if (st.listening) end('key');
      else begin('key');
    }
  };

  createEffect(pressed, isPressed => {
    if (!isPressed) return undefined;
    const stop = () => end('blur');
    const onVis = () => {
      if (document.hidden) stop();
    };
    window.addEventListener('blur', stop);
    document.addEventListener('visibilitychange', onVis);
    return () => {
      window.removeEventListener('blur', stop);
      document.removeEventListener('visibilitychange', onVis);
    };
  });

  createEffect(disabled, isDisabled => {
    if (isDisabled) end('disabled');
  });

  onSettled(() => {
    return () => {
      disposed = true;
      end('unmount');
      cancelAnimationFrame(st.raf);
      st.raf = 0;
      st.audio?.ctx.close();
    };
  });

  const style = (): JSX.CSSProperties => ({
    '--vp-accent': props.accentColor ?? '#f5f5f5',
    '--vp-icon': props.iconColor ?? '#a1a1aa',
    '--vp-bg': props.background ?? '#27272a',
    '--vp-size': `${size()}px`,
    '--vp-radius': `${radius()}px`,
    '--vp-reach': `${props.reach ?? 8}px`,
    '--vp-extra': `${extra()}px`,
    '--vp-clock-w': `${clockW()}px`,
    '--vp-wave-w': `${waveW()}px`,
    '--vp-stop': `${Math.round(size() * 0.32)}px`,
    '--vp-icon-size': `${Math.round(size() * 0.54)}px`,
    '--vp-time-size': `${timeSize()}px`,
    '--vp-open': `${props.openDuration ?? 200}ms`,
    '--vp-press': props.pressScale ?? 0.95,
    '--vp-hit': `${hit()}px`
  });

  return (
    <button
      type="button"
      disabled={disabled()}
      aria-label={props.ariaLabel ?? 'Dictate'}
      aria-pressed={listening() ? 'true' : 'false'}
      class={['voice-pill', props.className]}
      data-state={listening() ? 'listening' : 'idle'}
      data-pressed={pressed() ? '' : undefined}
      data-input={input()}
      data-time={showTime() ? '' : undefined}
      ref={el => (rootEl = el)}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      onLostPointerCapture={onPointerUp}
      onKeyDown={onKeyDown}
      onClick={onClick}
      onContextMenu={e => e.preventDefault()}
      style={style()}
    >
      <span class="voice-pill__capsule" aria-hidden="true" />
      <Show when={waveform()}>
        <canvas ref={el => (waveEl = el)} class="voice-pill__wave" aria-hidden="true" />
      </Show>
      <Show when={props.slideToCancel ?? true}>
        <span class="voice-pill__cancel" aria-hidden="true">
          <Icon icon={ArrowLeft01Icon} size={12} strokeWidth={2.2} />
          <span>Cancel</span>
        </span>
      </Show>
      <Show when={showTime()}>
        <span ref={el => (timeEl = el)} class="voice-pill__time" aria-hidden="true">
          0:00
        </span>
      </Show>
      <span class="voice-pill__glyph">
        <span class="voice-pill__mic">
          <Icon icon={Mic01Icon} size={Math.round(size() * 0.54)} strokeWidth={2} />
        </span>
        <span class="voice-pill__stop" aria-hidden="true" />
      </span>
    </button>
  );
}
